import{_ as t,c as s,o as r,j as n,Y as i,t as o}from"./chunks/framework.D-NV0Bun.js";const u=JSON.parse('{"title":"git-pack-refs | x-cmd man (git man1) | Pack heads and tags for efficient repository access","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-pack-refs - Pack heads and tags for efficient repository access","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-pack-refs | x-cmd man (git man1) | Pack heads and tags for efficient repository access"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-pack-refs - Pack heads and tags for efficient repository access"}]]},"headers":[],"params":{"isMan":true,"man":"git-pack-refs","category":"git man1","desc":"Pack heads and tags for efficient repository access"},"relativePath":"git/man1/git-pack-refs.md","filePath":"git/man1/[man].md"}'),c={name:"git/man1/git-pack-refs.md"},l={class:"visually-hidden"};function d(a,e,h,p,f,g){return r(),s("div",null,[n("h1",l,o(a.$params.man),1),e[0]||(e[0]=i('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-pack-refs - Pack heads and tags for efficient repository access</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack-refs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--all] [--no-prune]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Traditionally, tips of branches and tags (collectively known as <em>refs</em>) were stored one file per ref in a (sub)directory under <strong>$GIT_DIR/refs</strong> directory. While many branch tips tend to be updated often, most tags and some branch tips are never updated. When a repository has hundreds or thousands of tags, this one-file-per-ref format both wastes storage and hurts performance.</p><p>This command is used to solve the storage and performance problem by storing the refs in a single file, <strong>$GIT_DIR/packed-refs</strong>. When a ref is missing from the traditional <strong>$GIT_DIR/refs</strong> directory hierarchy, it is looked up in this file and used if found.</p><p>Subsequent updates to branches always create new files under <strong>$GIT_DIR/refs</strong> directory hierarchy.</p><p>A recommended practice to deal with a repository with too many refs is to pack its refs with <strong>--all</strong> once, and occasionally run <strong>git pack-refs</strong>. Tags are by definition stationary and are not expected to change. Branch heads will be packed with the initial <strong>pack-refs --all</strong>, but only the currently active branch heads will become unpacked, and the next <strong>pack-refs</strong> (without <strong>--all</strong>) will leave them unpacked.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--all</p><blockquote><p>The command by default packs all tags and refs that are already packed, and leaves other refs alone. This is because branches are expected to be actively developed and packing their tips does not help performance. This option causes branch tips to be packed as well. Useful for a repository with many branches of historical interests.</p></blockquote><p>--no-prune</p><blockquote><p>The command usually removes loose refs under <strong>$GIT_DIR/refs</strong> hierarchy after packing them. This option tells it not to.</p></blockquote><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Older documentation written before the packed-refs mechanism was introduced may still say things like &quot;.git/refs/heads/&lt;branch&gt; file exists&quot; when it means &quot;branch &lt;branch&gt; exists&quot;.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>',18))])}const k=t(c,[["render",d]]);export{u as __pageData,k as default};
